import{_ as e}from"./chunks/fs06-0._-bfDwD6.js";import{_ as o}from"./chunks/fs06-1.BYZknAE2.js";import{_ as r,a}from"./chunks/fs11-1.gbHjSq1J.js";import{_ as l,o as n,c as i,a4 as s}from"./chunks/framework.B0hSrcZ6.js";const g="/cases-img/fs09-1.jpg",d="/cases-img/fs09-2.jpg",h="/cases-img/fs12-0.jpg",c="/cases-img/fs12-1.jpg",p="/cases-img/fs13-0.jpg",k="/cases-img/fs13-1.jpg",f="/cases-img/fs15-0.jpg",b="/cases-img/fs15-2.jpg",u="/cases-img/fs10-0.jpg",m="/cases-img/fs10-1.jpg",x="/cases-img/fs14-0.jpg",y="/cases-img/fs14-1.jpg",S=JSON.parse('{"title":"铁柱的实战长文与推文","description":"本页收录铁柱撰写的 Grok Bot 实战长文与推文合集。聚焦算力额度精算、外部协同、虚机防灾与架构演进，提供可直接照抄的提示词、实用脚本与任务分流方案。","frontmatter":{},"headers":[],"relativePath":"cases/tiezhu.md","filePath":"cases/tiezhu.md","lastUpdated":1792210948000}'),B={name:"cases/tiezhu.md"};function _(G,t,q,P,z,w){return n(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="铁柱的实战长文与推文" tabindex="-1">铁柱的实战长文与推文 <a class="header-anchor" href="#铁柱的实战长文与推文" aria-label="Permalink to &quot;铁柱的实战长文与推文&quot;">​</a></h1><p>跟做 Grok Bot 最容易踩<strong>三个坑</strong>。</p><ol><li>高耗任务全堆给主对话，两三天烧光整周额度。</li><li>云电脑一旦重置，环境工具全丢。</li><li>多个 Bot 进群循环唤醒，瞬间耗尽用量。</li></ol><p>这里收录了铁柱（@cgnot996）的 <strong>9 篇实战长文与 4 篇系统推文合集</strong>，涵盖订阅额度与外部协同、防灾备份和架构选型四个主题。每篇都附带人工摘要卡与直达链接，方便直接照抄提示词、脚本与分流方案。</p><h2 id="订阅方案与算力额度精打细算" tabindex="-1">订阅方案与算力额度精打细算 <a class="header-anchor" href="#订阅方案与算力额度精打细算" aria-label="Permalink to &quot;订阅方案与算力额度精打细算&quot;">​</a></h2><h3 id="额度机制与分流策略" tabindex="-1">额度机制与分流策略 <a class="header-anchor" href="#额度机制与分流策略" aria-label="Permalink to &quot;额度机制与分流策略&quot;">​</a></h3><p>官方按每周共享池计费。<strong>每轮交互都会全量重读历史</strong>，直接在主对话贴长文档或长代码会让上下文暴涨，后续每次改动都在重复付费。</p><p><strong>主对话只留关键结论与文件路径</strong>，长资料存进工作目录，重活分流给后台：</p><ul><li>写代码交给命令行工具 Grok Build。</li><li>日常监控交给系统底层定时脚本。</li><li>图片与音视频解析在命令行出纯文本摘要后再返回。</li></ul><p>日常验收看两条指标：</p><ul><li>每周刷新日前保留 20% 以上用量。</li><li><strong>关闭按量付费</strong>，杜绝后台死循环与轮询空转。</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">档位</th><th style="text-align:left;">月费</th><th style="text-align:left;">建议与额度</th></tr></thead><tbody><tr><td style="text-align:left;">Plus</td><td style="text-align:left;">8 美元/月</td><td style="text-align:left;">不含 Bot，仅适合轻量开发</td></tr><tr><td style="text-align:left;">Premium</td><td style="text-align:left;">30 美元/月</td><td style="text-align:left;">开启 Bot 门槛，周额度 4 倍</td></tr><tr><td style="text-align:left;">Super</td><td style="text-align:left;">100 美元/月</td><td style="text-align:left;">高频调度多 Agent，周额度 15 倍</td></tr><tr><td style="text-align:left;">Ultra</td><td style="text-align:left;">200 美元/月</td><td style="text-align:left;">适合专业团队，周额度 50 倍</td></tr></tbody></table><p>把规则发给主力 Bot 即可生效：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后长资料、排查日志和中间结果都存成 /workspace/ 下的文件，回我时只给结论和文件路径，不要把原文贴回聊天。给你自己建一个 notes.md 记录角色、正在做的事和做过的决定，每做完一段就更新。面对批量处理或长流程任务，先使用 1 到 2 个最小样本进行单步验证，完成单步后必须暂停等待我确认。</span></span></code></pre></div><h3 id="大一统-x-订阅解读-新用户怎么选-老订阅要不要切换-一文讲清楚" tabindex="-1">大一统 X 订阅解读：新用户怎么选，老订阅要不要切换？一文讲清楚 <a class="header-anchor" href="#大一统-x-订阅解读-新用户怎么选-老订阅要不要切换-一文讲清楚" aria-label="Permalink to &quot;大一统 X 订阅解读：新用户怎么选，老订阅要不要切换？一文讲清楚&quot;">​</a></h3><p>新方案分 Plus、Premium、Super 和 Ultra 四档。</p><ul><li>选档：要用 Grok Bot 和云端自动化，<strong>起步选每月 30 美元的 Premium 档</strong>，普通用户按月开就行。</li><li>避坑：网页端操作单向不可逆，<strong>切换新订阅会永久解绑旧计划</strong>。操作前务必核对第三方模型调用频次，防止成本激增。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Myw6wFW8EicOiRkoEAXcVJqinee" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="铁柱推文合集1-开通、套餐与额度" tabindex="-1">铁柱推文合集①：开通、套餐与额度 <a class="header-anchor" href="#铁柱推文合集1-开通、套餐与额度" aria-label="Permalink to &quot;铁柱推文合集①：开通、套餐与额度&quot;">​</a></h3><p>新手防几天烧光额度，记住<strong>用量额度高于一切</strong>。</p><ol><li>开通选 <strong>30 美元订阅</strong>，直接起中文名，Bot 默认就会回中文。</li><li>推理模型固定选 <strong>Grok 4.5</strong>。</li><li>多 Bot 协同只走点对点通信，杜绝常驻群聊，防每条消息多方重读刷爆额度。</li></ol><p>三大用量黑洞千万别碰：</p><ul><li>视频生成</li><li>高频且无实质产出的定时器</li><li>多 Bot 群聊</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/PCZIw5IqgiZLjTkXqNncpxannpc" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="杭州线下活动回看-我是怎么让-grok-bot-额度更耐用的" tabindex="-1">杭州线下活动回看：我是怎么让 Grok Bot 额度更耐用的 <a class="header-anchor" href="#杭州线下活动回看-我是怎么让-grok-bot-额度更耐用的" aria-label="Permalink to &quot;杭州线下活动回看：我是怎么让 Grok Bot 额度更耐用的&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2096415217710461078" target="_blank" rel="noreferrer">杭州线下活动回看：我是怎么让 Grok Bot 额度更耐用的</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+g+'" alt="杭州线下活动回看：我是怎么让 Grok Bot 额度更耐用的" decoding="async"></p><p><img src="'+d+'" alt="杭州线下活动回看：我是怎么让 Grok Bot 额度更耐用的" loading="lazy" decoding="async"></p><p>想避免周额度提前跑光，要把<strong>调度与执行彻底分流</strong>。<strong>Grok Bot 负责需求拆解与结果验收</strong>，写代码等重型工作交给虚拟机里的无头模式 Grok Build 执行。</p><p>虚拟机远程登录卡顿，按两步解决。</p><ol><li>先在本机完成正常登录与授权。</li><li>再将允许迁移的配置导入虚拟机。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/D04JwEvL7iss9UkDBvLcLuvyncf" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-额度再省一点-定时任务极限优化" tabindex="-1">Grok Bot 额度再省一点：定时任务极限优化 <a class="header-anchor" href="#grok-bot-额度再省一点-定时任务极限优化" aria-label="Permalink to &quot;Grok Bot 额度再省一点：定时任务极限优化&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2107418115412046064" target="_blank" rel="noreferrer">Grok Bot 额度再省一点：定时任务极限优化</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+h+'" alt="Grok Bot 额度再省一点：定时任务极限优化" loading="lazy" decoding="async"></p><p><img src="'+c+'" alt="Grok Bot 额度再省一点：定时任务极限优化" loading="lazy" decoding="async"></p><p>定时 Routine 到点频繁空转很耗额度，省钱办法是<strong>把检查与判断彻底解耦</strong>。</p><ol><li>把“单纯等变化”的任务从常规 Routine 剥离，只留“到点必交付”。</li><li>虚拟机内写轻量 Shell 脚本，靠底层 cron <strong>每半小时</strong>查一次，只做基础比对，绝不调大模型。</li><li>检测到实质变动才通过 <strong>Webhook 唤醒 Bot</strong>，把常规空转消耗压至零。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SDr3wRrG5iGmz1kejdTcss0Rned" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-额度超长续航保姆级新手指南-直接发给-bot" tabindex="-1">Grok Bot 额度超长续航保姆级新手指南（直接发给 Bot！） <a class="header-anchor" href="#grok-bot-额度超长续航保姆级新手指南-直接发给-bot" aria-label="Permalink to &quot;Grok Bot 额度超长续航保姆级新手指南（直接发给 Bot！）&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2108504325609984233" target="_blank" rel="noreferrer">Grok Bot 额度超长续航保姆级新手指南（直接发给 Bot！）</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+p+'" alt="Grok Bot 额度超长续航保姆级新手指南（直接发给 Bot！）" loading="lazy" decoding="async"></p><p><img src="'+k+'" alt="Grok Bot 额度超长续航保姆级新手指南（直接发给 Bot！）" loading="lazy" decoding="async"></p><p>Bot 每次对话都全量重读历史，额度两三天就会见底。这 12 条实测规则能直接压住消耗。</p><ol><li><strong>看图和音视频先在命令行转文字摘要</strong>，不直接传多模态。</li><li>把长资料与排查日志写入文件，对话框只回传简短结论和路径。</li><li><strong>账户主动关掉按量付费或调低限额</strong>，防账单失控。</li><li><strong>报错重试设 2 次上限</strong>，连续失败立刻中断并找人工，掐死死循环空转。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/OPMJw2EgtiWMiJkcrzFc6gJ8nlf" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="自动化入库与外部协同网络" tabindex="-1">自动化入库与外部协同网络 <a class="header-anchor" href="#自动化入库与外部协同网络" aria-label="Permalink to &quot;自动化入库与外部协同网络&quot;">​</a></h2><h3 id="自动化管道与协同配置" tabindex="-1">自动化管道与协同配置 <a class="header-anchor" href="#自动化管道与协同配置" aria-label="Permalink to &quot;自动化管道与协同配置&quot;">​</a></h3><p>配上 Webhook，Grok Bot 就是 <strong>7×24 小时自动化节点</strong>。</p><ol><li>Bot 端建例行任务，触发选“当 Webhook 被触发时”，保存后获取接口地址与 Bearer 密钥。</li><li>手机用快捷指令配“获取 URL 内容”，以 POST 发送 JSON 文字或链接。</li><li>微信无分享面板就读剪贴板；大附件或多图存临时网盘换公网链接，Bot 云端下载解压。</li><li>飞书走长连接，免公网 IP 和自建服务器，配门铃触发器定向派活。</li></ol><p><strong>验收标准</strong>：</p><ul><li>手机即发即走不用等。</li><li>Bot 云端异步抓取、抽帧转录、落库并给收录回执。</li><li>群聊仅被精准艾特或全员时响应。</li></ul><p>发提示词可<strong>自动生成接收端点</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我创建一个 Webhook 触发的例行任务。快捷指令会用 POST 请求发来一个 JSON，里面包含一个字段 info。info 可能是我输入的文字，也可能是一个文件下载链接，比如微信聊天记录压缩包、截图、录音。收到后：如果是链接就先下载文件再读取，压缩包先解压；然后整理出要点，收录进知识库，最后给我一份回执，写清楚收录了什么、存在哪里。</span></span></code></pre></div><h3 id="grok-bot-webhook-快捷指令-知识自动入库流水线搭建" tabindex="-1">Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建 <a class="header-anchor" href="#grok-bot-webhook-快捷指令-知识自动入库流水线搭建" aria-label="Permalink to &quot;Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2097487429104197688" target="_blank" rel="noreferrer">Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+e+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"></p><p><img src="'+o+'" alt="Grok Bot Webhook + 快捷指令：知识自动入库流水线搭建" loading="lazy" decoding="async"></p><p>适合苹果用户随手归档图文和视频，<strong>手机发完即走，云端负责转录、抽帧和整理</strong>。</p><ol><li>在 Grok Bot 建例行任务，拿到专属 Webhook 地址与 Bearer 密钥。</li><li>手机快捷指令建 POST 请求，把链接或文字打包发送。</li><li>微信等没有系统分享面板的软件，<strong>做个读剪贴板的弹窗指令</strong>唤醒收集。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Kxtxw9gLBiqi0nkhZpCc7le5nrh" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="微信聊天记录打通-grok-bot-快捷指令进阶版" tabindex="-1">微信聊天记录打通 Grok Bot：快捷指令进阶版 <a class="header-anchor" href="#微信聊天记录打通-grok-bot-快捷指令进阶版" aria-label="Permalink to &quot;微信聊天记录打通 Grok Bot：快捷指令进阶版&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2107039351519707602" target="_blank" rel="noreferrer">微信聊天记录打通 Grok Bot：快捷指令进阶版</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+r+'" alt="微信聊天记录打通 Grok Bot：快捷指令进阶版" loading="lazy" decoding="async"></p><p><img src="'+a+'" alt="微信聊天记录打通 Grok Bot：快捷指令进阶版" loading="lazy" decoding="async"></p><p>这套方案走“快捷指令 + 临时网盘 + Webhook”链路。</p><ol><li>微信合并转发记录生成 ZIP，快捷指令自动上传到公网临时存储。</li><li>Webhook 通知 Bot 下载解压，提炼要点入库并回传结构化回执。</li></ol><p><strong>收录前必须在微信里手动点开所有图片和文件加载</strong>，防止转发空包丢数据。公网跳板顺便抹平了手机和电脑的存储路径差异。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/IwrfwYt1ti0aDWk3YEdcGyQRnUb" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-团队接入飞书保姆级教程-附飞书管家模板" tabindex="-1">Grok Bot 团队接入飞书保姆级教程（附飞书管家模板） <a class="header-anchor" href="#grok-bot-团队接入飞书保姆级教程-附飞书管家模板" aria-label="Permalink to &quot;Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2109247903785198076" target="_blank" rel="noreferrer">Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+f+'" alt="Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）" loading="lazy" decoding="async"></p><p><img src="'+b+'" alt="Grok Bot 团队接入飞书保姆级教程（附飞书管家模板）" loading="lazy" decoding="async"></p><p><strong>不用公网 IP 和自备服务器</strong>，靠飞书长连接与官方 Python SDK 扫码免配后台，把 3 个 Bot 接进飞书。每个 Bot 设独立门铃触发器，由应用管家维护账本。</p><ul><li><strong>严格限制仅在艾特自身或全员时转发</strong>，避免群内闲聊引发模型空转。</li><li><strong>关键确认节点直接推送交互卡片</strong>，点选按钮即可放行，省去两端界面来回切换的麻烦。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/F2VXw4hVbirRUjk5QgFcWS0jnJg" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="虚拟机防灾与记忆资产备份" tabindex="-1">虚拟机防灾与记忆资产备份 <a class="header-anchor" href="#虚拟机防灾与记忆资产备份" aria-label="Permalink to &quot;虚拟机防灾与记忆资产备份&quot;">​</a></h2><h3 id="灾备机制与资产分类" tabindex="-1">灾备机制与资产分类 <a class="header-anchor" href="#灾备机制与资产分类" aria-label="Permalink to &quot;灾备机制与资产分类&quot;">​</a></h3><p>所有 Bot 共享同一 Linux 底座（至强 8 核 8 线程、16GB 内存与 128GB 硬盘，作者自述未核）。<strong>不同 Bot 会话独立但底层文件系统打通</strong>，官方无原生导出。</p><table tabindex="0"><thead><tr><th>场景</th><th>保留</th><th>丢失与影响</th></tr></thead><tbody><tr><td>系统更新</td><td>工作目录与部分凭据</td><td>抹掉常驻进程、定时任务与全局包</td></tr><tr><td>整机重置</td><td>无保留</td><td>系统盘格式化，非持久化数据全丢</td></tr></tbody></table><p>手动备份不现实，<strong>必须把重建逻辑代码化</strong>。灾后在新环境跑总入口脚本，通过健康检查恢复运转。</p><table tabindex="0"><thead><tr><th>资产</th><th>路径与文件</th><th>恢复策略与坑点</th></tr></thead><tbody><tr><td>记忆设定</td><td>私有Git：agent-spec.md、profile.md、MEMORY.md</td><td>按清单读入新Bot，还原度约80%（作者自述，未核）</td></tr><tr><td>常驻服务</td><td>私有Git vm-services/：REGISTRY.md、registry.json、源码</td><td>靠restore-*.sh幂等重装并通过健康检查</td></tr><tr><td>访问凭证</td><td>本地 ~/.agents/secrets/：.env（chmod 600）</td><td><strong>严禁进 Git 或日志</strong>，灾后人工按总账填入</td></tr></tbody></table><p>配给独立运维 Bot 以下提示词，维护服务总账与恢复脚本。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是「虚拟机服务管家」，负责维护这台机器部署的所有第三方服务。你维护一份登记总账（REGISTRY.md 与 registry.json）、每个服务的独立恢复脚本（restore/restore-&lt;服务&gt;.sh，必须幂等可重复运行）、总入口 restore/restore-all.sh，以及一份排除日志和密钥的自写源码备份 service-src/。总账记录服务 ID、用途、安装方式、启停命令、健康检查命令和密钥存放路径。仓库严禁存入明文密钥。收到恢复指令后，按依赖顺序跑脚本并逐项交出健康检查验收清单。</span></span></code></pre></div><h3 id="grok-bot-百万撤离-一套完善的-agent-系统备份方案" tabindex="-1">Grok Bot 百万撤离：一套完善的 Agent 系统备份方案 <a class="header-anchor" href="#grok-bot-百万撤离-一套完善的-agent-系统备份方案" aria-label="Permalink to &quot;Grok Bot 百万撤离：一套完善的 Agent 系统备份方案&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2098222795847315967" target="_blank" rel="noreferrer">Grok Bot 百万撤离：一套完善的 Agent 系统备份方案</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+u+'" alt="Grok Bot 百万撤离：一套完善的 Agent 系统备份方案" loading="lazy" decoding="async"></p><p><img src="'+m+'" alt="Grok Bot 百万撤离：一套完善的 Agent 系统备份方案" loading="lazy" decoding="async"></p><p>官方没做一键导出记忆。这套方案调用 Bot 读上下文，把人设、决策和任务快照写成 Markdown，分层推到私有 Git。</p><ul><li>备份只存纯文本，版本演进交给 Git。</li><li><strong>仓库必须扫密钥，只记 Token 路径不留明文</strong>。</li><li><strong>新账号重建还原度约 80%</strong>，也能直接迁入本地系统。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/W0TCwnTmbiIJ9KkF4S4cV6ifnCh" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="grok-bot-虚拟机重置后工具全没了-备份恢复教程-附提示词" tabindex="-1">Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词） <a class="header-anchor" href="#grok-bot-虚拟机重置后工具全没了-备份恢复教程-附提示词" aria-label="Permalink to &quot;Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词）&quot;">​</a></h3><blockquote><p>来源：<a href="https://x.com/cgnot996/status/2108874629163229628" target="_blank" rel="noreferrer">Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词）</a><br> 作者：<a href="https://x.com/cgnot996" target="_blank" rel="noreferrer">铁柱AGI @cgnot996</a></p></blockquote><p><img src="'+x+'" alt="Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词）" loading="lazy" decoding="async"></p><p><img src="'+y+'" alt="Grok Bot 虚拟机重置后工具全没了？备份恢复教程（附提示词）" loading="lazy" decoding="async"></p><p>云电脑重置后，<strong>把服务重建逻辑代码化</strong>最省心。在私有 Git 仓库建 <code>REGISTRY.md</code> 服务总账，收录 20 个项目的依赖、启停命令与无密钥源码，写好幂等恢复脚本。</p><ol><li>明确区分系统更新与整机重置的丢失边界。</li><li>按照底层包、CLI 工具到常驻进程的顺序跑恢复脚本。</li><li><strong>每跑完一步立即做健康检查</strong>，遇到故障先跳过并记入清单，<strong>杜绝盲目重置</strong>。</li></ol><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/Q6ZdwzjO5i6z0pkdMfyca8Cbnye" target="_blank" rel="noreferrer">阅读原文</a></p><h2 id="架构演进、业务实战与生态选型" tabindex="-1">架构演进、业务实战与生态选型 <a class="header-anchor" href="#架构演进、业务实战与生态选型" aria-label="Permalink to &quot;架构演进、业务实战与生态选型&quot;">​</a></h2><h3 id="矩阵分工与选型评估" tabindex="-1">矩阵分工与选型评估 <a class="header-anchor" href="#矩阵分工与选型评估" aria-label="Permalink to &quot;矩阵分工与选型评估&quot;">​</a></h3><p>平时用 Agent 要坚持“一人一岗”。<strong>别把写代码、抓数据，连同生活归档与发帖全塞给同一个 Bot</strong>，提示词容易冲突，超长上下文也会把模型带偏。</p><p>平台选型可以参考铁柱的“品牌整机”与“DIY 组装机”对比：</p><table tabindex="0"><thead><tr><th style="text-align:left;">路线</th><th style="text-align:left;">代表产品</th><th style="text-align:left;">优势</th><th style="text-align:left;">适用场景与局限</th></tr></thead><tbody><tr><td style="text-align:left;">品牌整机</td><td style="text-align:left;">Grok Bot、Muse</td><td style="text-align:left;">云电脑开箱即用，免运维远程会话与应用集成</td><td style="text-align:left;">受官方周额度与规则限制；适合重度依赖社交分发与云端托管</td></tr><tr><td style="text-align:left;">DIY 组装机</td><td style="text-align:left;">本地开源 Hermes、DS Bot</td><td style="text-align:left;">自由挂载开源模型，无额度限制，数据高度私有</td><td style="text-align:left;">需要自己搭系统、调脚本；适合纯代码开发与定制模型微调</td></tr></tbody></table><p>业务落地要守住安全与自动化底线：</p><ul><li>机械性的抓取数据和录入表格做到全自动化。</li><li>涉及公开社交运营或资金变动，必须保留人工确认闸门。</li><li><strong>发帖必须走官方 API，严禁在云电脑里用无头浏览器模拟登录</strong>，避免账号被封。</li></ul><p>岗位分工与避坑参考：</p><table tabindex="0"><thead><tr><th style="text-align:left;">业务岗位</th><th style="text-align:left;">常驻 Bot</th><th style="text-align:left;">职责</th><th style="text-align:left;">安全边界与避坑配置</th></tr></thead><tbody><tr><td style="text-align:left;">代码与运维</td><td style="text-align:left;">仓库管理员、SEO 监控</td><td style="text-align:left;">每日监测项目、自动合并 PR、补全指引</td><td style="text-align:left;"><strong>检查定时任务日历</strong>，避免误设仅工作日执行导致周末停摆</td></tr><tr><td style="text-align:left;">生活与归档</td><td style="text-align:left;">记账管家、知识库收录</td><td style="text-align:left;">接收快捷指令推送的图文，录入多维表格</td><td style="text-align:left;">临时图床设置高强度随机 ID，敏感隐私不走公网跳板</td></tr><tr><td style="text-align:left;">协作与调度</td><td style="text-align:left;">文章主编、虚拟机管家</td><td style="text-align:left;">拆解选题、协调各 Bot、管理后台总账</td><td style="text-align:left;">外部工具采用设备代码（Device Code）授权，防止两台机器互相顶掉登录态</td></tr></tbody></table><h3 id="铁柱推文合集2-产品功能与版本观察" tabindex="-1">铁柱推文合集②：产品功能与版本观察 <a class="header-anchor" href="#铁柱推文合集2-产品功能与版本观察" aria-label="Permalink to &quot;铁柱推文合集②：产品功能与版本观察&quot;">​</a></h3><p>作者：铁柱AGI（推文合集）｜适合谁读：关注底层环境机制、想掌握多端联动与网络排错的技术探索者</p><p>合集记录了 Grok Bot 的底层演进。<strong>同一账号下的所有 Bot 共享同一台 Linux 云电脑</strong>，配置是 8 核 16G 内存配 128G 硬盘，各桌面会话相互独立。文中还记录了专属邮箱申领、调用原生 X 搜索与排查出口网络的方法。</p><p>环境排障重点记住两点：</p><ul><li><strong>Webhook 面板点击没反应时，直接发指令让 Bot 回复直达链接。</strong></li><li>核心环境配置与自定义脚本必须收敛到持久化路径，避免系统底层更替带来损耗。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/ZRFQwIlNgiuJTVkGcJgcrZhsnKd" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="铁柱推文合集3-实战玩法与案例" tabindex="-1">铁柱推文合集③：实战玩法与案例 <a class="header-anchor" href="#铁柱推文合集3-实战玩法与案例" aria-label="Permalink to &quot;铁柱推文合集③：实战玩法与案例&quot;">​</a></h3><p>作者：铁柱AGI（推文合集）｜适合谁读：找业务落地灵感、想避开自动化封号和死循环的实践者</p><p>铁柱记录了十余个真实运行的 Bot 岗位，包括仓库巡检与 SEO 日报，也涵盖微信抓取、多维表格记账及拼图接口调用，并给出了从单岗配置到持久化灾备的四步实施法则。</p><p>平稳运行必须遵守两项运维规范：</p><ul><li><strong>发布内容必须走官方 API，严禁在虚拟机内用无头浏览器模拟发帖</strong>，防止账号受限。</li><li><strong>外部命令行工具统一用设备代码（Device Code）授权</strong>，防止两台机器争夺凭证导致掉线。</li></ul><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/SMztw0FlBilqx5k1tXzc9kFjndb" target="_blank" rel="noreferrer">阅读原文</a></p><h3 id="铁柱推文合集4-社区、生态与竞品对照" tabindex="-1">铁柱推文合集④：社区、生态与竞品对照 <a class="header-anchor" href="#铁柱推文合集4-社区、生态与竞品对照" aria-label="Permalink to &quot;铁柱推文合集④：社区、生态与竞品对照&quot;">​</a></h3><p>作者：铁柱AGI（推文合集）｜适合谁读：在多个 Agent 框架间权衡、评估选型与找开源资源的架构师</p><p>铁柱横向对比了主流 Agent 框架与 Grok Bot。Grok Bot 属于整机路线，自带云电脑开箱即用但受额度限制；Hermes 等组装机高度可控，需要自己运维。</p><p>文里也总结了 awesome-grok-bot 仓库靠 Bot 自主巡检收录活动与文档的经验。</p><p>团队扩充认知有个实用技巧：<strong>直接把优质开源框架和外部教程当成上下文发给 Bot 学习</strong>，让 Agent 紧贴自身工作流。</p><p><a href="https://jcng5q8n0f3z.feishu.cn/wiki/RMRTwk3MqiUqEwk0TzTchA4LnDg" target="_blank" rel="noreferrer">阅读原文</a></p>',125)])])}const T=l(B,[["render",_]]);export{S as __pageData,T as default};
